<?php
require_once __DIR__.'/auth/require_login.php';
require_once __DIR__.'/api/db.php';
require_once __DIR__.'/ai/functions.php';
header('Cache-Control: no-store');
function esc($s):string{return htmlspecialchars((string)$s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$pid=filter_var($_GET['project_id']??$_POST['project_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);
if(!$pid){http_response_code(400);exit('Project ID missing.');}
$uid=(int)$_SESSION['user_id'];$project=ai_require_project($pdo,(int)$pid,$uid);
$message='';
try {
 if($_SERVER['REQUEST_METHOD']==='POST'){
  if(!valid_csrf()){http_response_code(403);exit('Invalid CSRF token.');}
  $action=$_POST['action']??'';
  if($action==='create') {$rid=ai_create_request($pdo,(int)$pid,$uid);$message='New pending AI request created: '.$rid.'. Run the Windows AI worker from PowerShell to generate four ZIPs.';}
  elseif($action==='import'){
   $jid=(int)($_POST['job_id']??0);$q=$pdo->prepare("SELECT id FROM ai_generation_jobs WHERE id=? AND project_id=? AND user_id=? AND status='pending'");$q->execute([$jid,$pid,$uid]);
   if(!$q->fetchColumn())throw new RuntimeException('Invalid pending job.');
   ai_import_zip($pdo,$jid,(int)$pid,$uid,(int)($_POST['design_number']??0),trim((string)($_POST['style_name']??'')),$_FILES['design_zip']??[]);
   $message='Design ZIP imported. All four must be imported before selection.';
  } elseif($action==='select') {ai_select($pdo,(int)$pid,$uid,(int)($_POST['design_id']??0));$message='Selected design saved in database.';}
 }
} catch(Throwable $e){$message=$e->getMessage();}
$q=$pdo->prepare('SELECT * FROM ai_generation_jobs WHERE project_id=? AND user_id=? ORDER BY id DESC');$q->execute([$pid,$uid]);$jobs=$q->fetchAll(PDO::FETCH_ASSOC);
$q=$pdo->prepare('SELECT d.*,j.request_id FROM ai_generated_designs d JOIN ai_generation_jobs j ON j.id=d.job_id WHERE d.project_id=? AND d.user_id=? ORDER BY d.id DESC');$q->execute([$pid,$uid]);$designs=$q->fetchAll(PDO::FETCH_ASSOC);
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>AI Designs — <?=esc($project['name'])?></title><style>
:root{font-family:system-ui,Arial,sans-serif;color:#233044;background:#f2f5fa}body{margin:0}main{max-width:1050px;margin:34px auto;padding:0 18px}.panel{background:white;border:1px solid #d9e2ee;border-radius:16px;margin:18px 0;padding:22px;box-shadow:0 6px 20px #172b4d08}h1{font-size:30px}h2{font-size:21px}a{color:#145e9c}.btn,button{display:inline-block;background:#145e9c;color:white;border:0;border-radius:9px;padding:10px 16px;text-decoration:none;cursor:pointer;font:inherit}button:hover,.btn:hover{background:#104875}input,select{padding:9px;border:1px solid #a7b5c6;border-radius:7px;max-width:100%}label{display:block;margin:12px 0 4px}table{width:100%;border-collapse:collapse}td,th{padding:11px;border-bottom:1px solid #dce4ed;text-align:left}small,.muted{color:#52647b}.alert{padding:12px;background:#e8f3ff;border-radius:9px}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px}.cards>article{border:1px solid #d4e0ea;padding:14px;border-radius:12px}form.inline{display:inline-block;margin:8px 6px 0 0}pre{white-space:pre-wrap;word-break:break-word;max-height:300px;overflow:auto;background:#f5f7fa;padding:12px;border-radius:9px}@media(max-width:640px){table{display:block;overflow-x:auto}}
</style></head><body><main><p><a href="projects.php">← Back to My Projects</a></p><h1>AI Designs — <?=esc($project['name'])?></h1><p class="muted">Save a fresh request with hotel details, 3 FAQs and gallery references. Create a request, then run the local Windows Codex worker from PowerShell. The worker uses your separately authorized Codex CLI sign-in; it does not use an API key. Logo-based colors require a saved logo asset, which is not yet part of this database schema.</p>
<?php if($message):?><p class="alert" role="status"><?=esc($message)?></p><?php endif;?>
<section class="panel"><h2>1. Create fresh 4-design request</h2><p>Each click stores a new snapshot and system prompt. After creating a request, run the trusted local Windows Codex worker using the command in the setup guide. Do not run the worker from the browser.</p><form method="post"><input type="hidden" name="csrf_token" value="<?=esc(csrf_token())?>"><input type="hidden" name="project_id" value="<?=$pid?>"><input type="hidden" name="action" value="create"><button>Create new AI request</button></form></section>
<section class="panel"><h2>2. Pending requests and AI handoff</h2><?php if(!$jobs):?><p>No requests yet.</p><?php endif;?><?php foreach($jobs as $job):?><details><summary><strong>Request <?=esc($job['request_id'])?></strong> — <?=esc($job['status'])?> — <?=esc($job['created_at'])?></summary><p>The local CLI worker can process this pending request. It is deliberately not triggered from the web page.</p><h3>System prompt</h3><pre><?=esc($job['system_prompt'])?></pre><h3>Saved hotel information</h3><pre><?=esc(json_encode(json_decode($job['input_json'],true),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE))?></pre></details><?php endforeach;?></section>
<section class="panel"><h2>3. Import generated ZIP designs</h2><p>The Windows Codex worker can register all four ZIPs automatically. This upload remains available for manually generated, authorized ZIPs.</p><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=esc(csrf_token())?>"><input type="hidden" name="project_id" value="<?=$pid?>"><input type="hidden" name="action" value="import"><label for="job">Pending request</label><select name="job_id" id="job" required><?php foreach($jobs as $job)if($job['status']==='pending'):?><option value="<?=$job['id']?>"><?=esc($job['request_id'])?></option><?php endif;?></select><label for="num">Design number</label><select id="num" name="design_number" required><?php foreach([1=>'Cinematic Luxury',2=>'Modern Editorial',3=>'Warm Boutique',4=>'Clean Contemporary'] as $n=>$s):?><option value="<?=$n?>"><?=$n?> — <?=esc($s)?></option><?php endforeach;?></select><label for="style">Style name</label><input id="style" name="style_name" maxlength="90" required placeholder="e.g. Cinematic Luxury"><label for="zip">Generated ZIP (max 25 MB)</label><input id="zip" type="file" name="design_zip" accept=".zip,application/zip" required><p><button>Import ZIP</button></p></form></section>
<section class="panel"><h2>4. Completed designs — choose and download</h2><div class="cards"><?php foreach($designs as $d):?><article><h3>Design <?=$d['design_number']?> — <?=esc($d['style_name'])?></h3><p class="muted">Request <?=esc($d['request_id'])?></p><?php if($d['selected_at']):?><strong>✓ Selected</strong><?php endif;?><p><a class="btn" href="ai/download.php?design_id=<?=$d['id']?>">Download ZIP</a></p><form method="post"><input type="hidden" name="csrf_token" value="<?=esc(csrf_token())?>"><input type="hidden" name="project_id" value="<?=$pid?>"><input type="hidden" name="action" value="select"><input type="hidden" name="design_id" value="<?=$d['id']?>"><button>Select design</button></form></article><?php endforeach;?></div><?php if(!$designs):?><p>No generated ZIPs imported yet.</p><?php endif;?></section></main></body></html>
